import{_ as i,o as a,c as n,a2 as e}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"📊 TDengine 海量时序存储","description":"","frontmatter":{},"headers":[],"relativePath":"iot/tdengine.md","filePath":"iot/tdengine.md"}'),t={name:"iot/tdengine.md"};function l(h,s,p,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="📊-tdengine-海量时序存储" tabindex="-1">📊 TDengine 海量时序存储 <a class="header-anchor" href="#📊-tdengine-海量时序存储" aria-label="Permalink to &quot;📊 TDengine 海量时序存储&quot;">​</a></h1><p>在工业物联网场景下，成百上千台传感器以秒级乃至百毫秒级频率上报数据，传统关系型数据库（如 MySQL）在数据量达到数千万行后查询变慢、存储膨胀严重。MzMedia 引入了国产高性能时序数据库 <strong>TDengine 3.0+</strong>。</p><hr><h2 id="_1-超级表-stable-建模设计" tabindex="-1">1. 超级表 (STable) 建模设计 <a class="header-anchor" href="#_1-超级表-stable-建模设计" aria-label="Permalink to &quot;1. 超级表 (STable) 建模设计&quot;">​</a></h2><p>TDengine 采用“一个设备一张表，一类设备一个超级表”的核心设计：</p><ul><li><strong>超级表 (STable)</strong>：定义同类设备的数据结构与静态标签（Tags，如 <code>tenant_id</code>, <code>product_key</code>, <code>device_id</code>, <code>location</code>）；</li><li><strong>子表 (SubTable)</strong>：每个物理设备对应超级表的一张独立子表，子表仅存储时间戳（<code>ts</code>）与动态属性（如 <code>current</code>, <code>voltage</code>, <code>temperature</code>）。</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 示例：温度传感器超级表定义</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> STABLE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `meters`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `ts`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TIMESTAMP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `current`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FLOAT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `voltage`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `temperature`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FLOAT</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) TAGS (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `tenant_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> BIGINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `device_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    `workshop`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="_2-核心性能优势" tabindex="-1">2. 核心性能优势 <a class="header-anchor" href="#_2-核心性能优势" aria-label="Permalink to &quot;2. 核心性能优势&quot;">​</a></h2><ol><li><strong>超强写入吞吐</strong>：单机每秒可并发写入数十万条记录，无锁无竞争写入；</li><li><strong>极高数据压缩比</strong>：针对时序数据特点采用列式压缩算法（LZ4 / 二阶差分），相比 MySQL 节约 <strong>80% 以上</strong> 的磁盘存储空间；</li><li><strong>毫秒级时序聚合</strong>：原生支持降采样查询（<code>INTERVAL(1h)</code>）、滑动窗口聚合（<code>ROLLING</code>）与插值填充，前端大屏加载全年历史趋势曲线秒级呈现。</li></ol>',10)])])}const c=i(t,[["render",l]]);export{g as __pageData,c as default};
